  const sectionEntries=entries.filter(c=>(c.live2d&&!EVENT_SKINS.has(c.id))===animated);if(!sectionEntries.length)continue;
  const section=document.createElement('section'),title=document.createElement('h3'),note=document.createElement('p'),cards=document.createElement('div');
  section.className='costume-section';title.textContent=animated?'Available':'Unavailable';note.className='small muted';note.textContent=animated?`Live2D costumes · ${ECONOMY.costumes.ticketPrice} each.`:'Event skins are redeemed in Events. Static costumes are free.';cards.className='costume-grid';
