function renderStampExchange(){setText($('stamp-balance'),fmt(game.state.expeditionStamps)+' expedition stamps');const grid=$('stamp-offers');grid.replaceChildren();for(const offer of game.stampOffers()){const card=document.createElement('section'),title=document.createElement('h3'),note=document.createElement('p'),button=document.createElement('button');card.className='commission-card';renderRewardChips(title,[{kind:offer.id.startsWith('fairy-')?'fairy':offer.id==='tickets'?'tickets':offer.id.slice(6),amount:1,name:offer.id.startsWith('fairy-')?offer.name:''}]);const locked=Math.min(...game.state.tiers)+1<offer.tier,maxed=offer.id.startsWith('fairy-')&&game.fairyLevel(offer.id)>=10;note.textContent=offer.cost+' stamps · Requires all three material families at tier '+offer.tier;button.textContent=locked?'Material tier locked':maxed?'Fairy maxed':'Exchange · '+offer.cost;button.disabled=locked||maxed||game.state.expeditionStamps<offer.cost;button.onclick=()=>{if(game.redeemStamps(offer.id)){save(true);render();renderStampExchange();notice(offer.name+' received from the Stamp Exchange.','success');}};card.append(title,note,button);grid.append(card);}}
